function WorkSuggestionAssistant({ item, onApply }: { item: WorkCapability; onApply: (patch: Partial<WorkCapability>) => void }) {
  const [suggestions, setSuggestions] = useState<CpvSuggestion[]>([]);
  const [selected, setSelected] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [searched, setSearched] = useState(false);

  async function search() {
    if (item.trade.trim().length < 3) { setError("Shkruani të paktën 3 shkronja për llojin e punës."); return; }
    setLoading(true); setError(""); setSearched(true);
    try {
      const response = await fetch("/api/company/capabilities/work-suggestions", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ query: item.trade }) });
      const body = await response.json() as { suggestions?: CpvSuggestion[]; error?: string };
      if (!response.ok) throw new Error(body.error ?? "Kërkimi dështoi.");
      const next = body.suggestions ?? [];
      setSuggestions(next);
      setSelected(next.filter((suggestion) => suggestion.score >= 70).map((suggestion) => suggestion.id));
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Kërkimi dështoi."); }
    finally { setLoading(false); }
  }

  function applySelected() {
    const accepted = suggestions.filter((suggestion) => selected.includes(suggestion.id));
    onApply({
      cpvPrefixes: [...new Set([...item.cpvPrefixes, ...accepted.map((suggestion) => suggestion.code)])],
      projectTypes: [...new Set([...item.projectTypes, ...accepted.flatMap((suggestion) => suggestion.projectTypes)])],
      buildingTypes: [...new Set([...item.buildingTypes, ...accepted.flatMap((suggestion) => suggestion.buildingTypes)])]
    });
    setSuggestions([]); setSelected([]); setSearched(false);
  }

  return <div className="work-suggestion-assistant field-wide">
    <div className="work-suggestion-head"><div><b>Gjej specializimet dhe CPV-të</b><p>Sistemi e analizon përshkrimin; asgjë nuk shtohet pa konfirmimin tuaj.</p></div><button type="button" disabled={loading} onClick={() => void search()}>{loading ? "Duke analizuar…" : "Sugjero specializimet"}</button></div>
    {error && <p className="work-suggestion-error" role="alert">{error}</p>}
    {searched && !loading && !error && suggestions.length === 0 && <p className="work-suggestion-empty">Nuk u gjet një përputhje e sigurt. Provoni një përshkrim më konkret, p.sh. “fasadë me panele alumini”.</p>}
    {suggestions.length > 0 && <><div className="cpv-suggestion-list" aria-label="Specializimet e sugjeruara">{suggestions.map((suggestion) => {
      const checked = selected.includes(suggestion.id);
      return <label key={suggestion.id} className={checked ? "selected" : ""}><input type="checkbox" checked={checked} onChange={(event) => setSelected((current) => event.target.checked ? [...current, suggestion.id] : current.filter((id) => id !== suggestion.id))} /><span><b>{suggestion.labelAl}</b><small>{suggestion.descriptionAl}</small><em>{suggestion.examples.join(" · ")}</em></span><code>CPV {suggestion.code}</code></label>;
    })}</div><div className="work-suggestion-actions"><span>{selected.length} specializime të zgjedhura</span><button type="button" disabled={selected.length === 0} onClick={applySelected}>Konfirmo dhe plotëso profilin</button></div></>}
  </div>;
}

