function FinancialSection({ model, setModel }: { model: CompanyCapabilityModel; setModel: SetModel }) {
  const financial = model.financialCapacity; const patch = (value: Partial<typeof financial>) => setModel((current) => ({ ...current, financialCapacity: { ...current.financialCapacity, ...value, updatedAt: new Date().toISOString() } }));
  return <><SectionIntro title="Kufijtë financiarë" copy="Këto të dhëna janë private dhe përdoren vetëm për filtrimin e kontratave dhe garancive." /><div className="financial-summary"><div><span>Kontrata maksimale</span><b>{money(financial.maxContractValueAll)}</b></div><div><span>Financim i disponueshëm</span><b>{money(financial.availableProjectFinancingAll)}</b></div><div><span>Backlog aktual</span><b>{money(financial.currentBacklogAll)}</b></div></div><div className="record-grid standalone-grid"><Field label="Kapitali qarkullues (ALL)"><input type="number" min="0" value={financial.workingCapitalAll ?? ""} onChange={(event) => patch({ workingCapitalAll: numberValue(event.target.value) })} /></Field><Field label="Linja krediti (ALL)"><input type="number" min="0" value={financial.creditFacilitiesAll ?? ""} onChange={(event) => patch({ creditFacilitiesAll: numberValue(event.target.value) })} /></Field><Field label="Financim projekti i lirë (ALL)"><input type="number" min="0" value={financial.availableProjectFinancingAll ?? ""} onChange={(event) => patch({ availableProjectFinancingAll: numberValue(event.target.value) })} /></Field><Field label="Kontrata maksimale (ALL)" required><input type="number" min="0" value={financial.maxContractValueAll ?? ""} onChange={(event) => patch({ maxContractValueAll: numberValue(event.target.value) })} /></Field><Field label="Backlog aktual (ALL)"><input type="number" min="0" value={financial.currentBacklogAll ?? ""} onChange={(event) => patch({ currentBacklogAll: numberValue(event.target.value) })} /></Field><Field label="Angazhim maksimal (ALL)"><input type="number" min="0" value={financial.maxConcurrentCommitmentAll ?? ""} onChange={(event) => patch({ maxConcurrentCommitmentAll: numberValue(event.target.value) })} /></Field><Field label="Garanci oferte (ALL)"><input type="number" min="0" value={financial.bidSecurityLimitAll ?? ""} onChange={(event) => patch({ bidSecurityLimitAll: numberValue(event.target.value) })} /></Field><Field label="Garanci performance (ALL)"><input type="number" min="0" value={financial.performanceGuaranteeLimitAll ?? ""} onChange={(event) => patch({ performanceGuaranteeLimitAll: numberValue(event.target.value) })} /></Field><Field label="Kufi sigurimi (ALL)"><input type="number" min="0" value={financial.insuranceLimitAll ?? ""} onChange={(event) => patch({ insuranceLimitAll: numberValue(event.target.value) })} /></Field><Field label="Kufi bonding (ALL)"><input type="number" min="0" value={financial.bondingLimitAll ?? ""} onChange={(event) => patch({ bondingLimitAll: numberValue(event.target.value) })} /></Field></div><SectionIntro title="Historiku i xhiros" copy="Shtoni vitet që përdoren zakonisht në kriteret e kualifikimit." action="Shto vit" onAdd={() => patch({ turnoverHistory: [...financial.turnoverHistory, { id: uid("turnover"), year: new Date().getFullYear() - 1, amountAll: 0 }] })} /><div className="turnover-table"><div><span>Viti</span><span>Xhiro vjetore (ALL)</span><span /></div>{financial.turnoverHistory.map((year) => <div key={year.id}><input type="number" aria-label="Viti" value={year.year} onChange={(event) => patch({ turnoverHistory: financial.turnoverHistory.map((item) => item.id === year.id ? { ...item, year: Number(event.target.value) } : item) })} /><input type="number" min="0" aria-label="Xhiro vjetore" value={year.amountAll} onChange={(event) => patch({ turnoverHistory: financial.turnoverHistory.map((item) => item.id === year.id ? { ...item, amountAll: Number(event.target.value) } : item) })} /><button type="button" onClick={() => patch({ turnoverHistory: financial.turnoverHistory.filter((item) => item.id !== year.id) })}>Hiq</button></div>)}</div></>;
}

function ExperienceSection({ items, add, patch, remove }: { items: ReferenceProject[]; add: (item: ReferenceProject) => void; patch: Patch<ReferenceProject>; remove: (id: string) => void }) {
  const addNew = () => add({ id: uid("project"), title: "", client: "", authority: "", cpvCodes: [], workTypes: [], valueAll: null, region: "", startDate: null, endDate: null, role: "main_contractor", status: "completed", outcome: "", referenceContact: "", documentIds: [], active: true });
  return <><SectionIntro title="Projektet reference" copy="Regjistroni kontratat që provojnë eksperiencë të ngjashme sipas punës, CPV dhe vlerës." action="Shto projekt" onAdd={addNew} />{items.length === 0 ? <EmptyCollection title="Nuk ka projekte reference" copy="Shtoni një kontratë të përfunduar për të përmirësuar matjen e eksperiencës." onAdd={addNew} /> : items.map((item) => <Card key={item.id} title={item.title || "Projekt i ri"} eyebrow={item.status === "completed" ? "I PËRFUNDUAR" : "NË ZBATIM"} onRemove={() => remove(item.id)}><Field label="Emri i projektit" required><input value={item.title} onChange={(event) => patch(item.id, { title: event.target.value })} /></Field><Field label="Klienti"><input value={item.client} onChange={(event) => patch(item.id, { client: event.target.value })} /></Field><Field label="Autoriteti kontraktor"><input value={item.authority} onChange={(event) => patch(item.id, { authority: event.target.value })} /></Field><Field label="Roli"><select value={item.role} onChange={(event) => patch(item.id, { role: event.target.value as ReferenceProject["role"] })}><option value="main_contractor">Kontraktor kryesor</option><option value="joint_venture">Bashkim operatorësh</option><option value="subcontractor">Nënkontraktor</option></select></Field><Field label="Kodet CPV"><input value={join(item.cpvCodes)} onChange={(event) => patch(item.id, { cpvCodes: split(event.target.value) })} /></Field><Field label="Llojet e punës"><input value={join(item.workTypes)} onChange={(event) => patch(item.id, { workTypes: split(event.target.value) })} /></Field><Field label="Vlera (ALL)"><input type="number" min="0" value={item.valueAll ?? ""} onChange={(event) => patch(item.id, { valueAll: numberValue(event.target.value) })} /></Field><Field label="Qarku"><input value={item.region} onChange={(event) => patch(item.id, { region: event.target.value })} /></Field><Field label="Fillimi"><input type="date" value={item.startDate ?? ""} onChange={(event) => patch(item.id, { startDate: event.target.value || null })} /></Field><Field label="Përfundimi"><input type="date" value={item.endDate ?? ""} onChange={(event) => patch(item.id, { endDate: event.target.value || null })} /></Field><Field label="Statusi"><select value={item.status} onChange={(event) => patch(item.id, { status: event.target.value as ReferenceProject["status"] })}><option value="completed">I përfunduar</option><option value="in_progress">Në zbatim</option></select></Field><Field label="Kontakti për referencë"><input value={item.referenceContact} onChange={(event) => patch(item.id, { referenceContact: event.target.value })} /></Field><Field label="Rezultati" wide><textarea rows={3} value={item.outcome} onChange={(event) => patch(item.id, { outcome: event.target.value })} placeholder="Dorëzimi, afati, penalitetet, cilësia…" /></Field></Card>)}</>;
}

function PartnersSection({ items, add, patch, remove }: { items: CapabilityPartner[]; add: (item: CapabilityPartner) => void; patch: Patch<CapabilityPartner>; remove: (id: string) => void }) {
  const addNew = () => add({ id: uid("partner"), name: "", partnerType: "subcontractor", categories: [], licences: [], regions: [], availability: "", dependencyRisk: "medium", jointVentureReady: false, active: true, approvalStatus: "pending", capabilities: [], resources: [], rates: [], performance: { completedProjects: 0, onTimeRate: null, qualityRating: null, lastUsedAt: null, notes: "" } });
  return <><SectionIntro title="Rrjeti i partnerëve" copy="Regjistroni aftësitë reale, burimet, çmimet dhe dokumentet e partnerëve që mund të mbulojnë pjesë të tenderit." action="Shto partner" onAdd={addNew} />{items.length === 0 ? <EmptyCollection title="Nuk ka partnerë" copy="Shtoni nënkontraktorë, kompani qiraje, laboratorë, furnitorë specialistë ose partnerë JV." onAdd={addNew} /> : items.map((item) => <Card key={item.id} title={item.name || "Partner i ri"} eyebrow={(item.partnerType ?? "subcontractor").replaceAll("_", " ").toUpperCase()} onRemove={() => remove(item.id)}>
    <Field label="Emri ligjor" required><input value={item.name} onChange={(event) => patch(item.id, { name: event.target.value })} placeholder="p.sh. Elektro Partner sh.p.k." /></Field>
    <Field label="Lloji"><select value={item.partnerType} onChange={(event) => patch(item.id, { partnerType: event.target.value as CapabilityPartner["partnerType"] })}><option value="subcontractor">Nënkontraktor pune</option><option value="equipment_rental">Kompani makinerish me qira</option><option value="strategic_partner">Partner strategjik / furnitor</option><option value="joint_venture">Partner JV</option></select></Field>
    <Field label="NIPT"><input value={item.nipt ?? ""} onChange={(event) => patch(item.id, { nipt: event.target.value.toUpperCase() })} /></Field>
    <Field label="Statusi"><select value={item.approvalStatus ?? "pending"} onChange={(event) => patch(item.id, { approvalStatus: event.target.value as CapabilityPartner["approvalStatus"] })}><option value="approved">Aprovuar</option><option value="pending">Në verifikim</option><option value="blocked">I bllokuar</option></select></Field>
    <Field label="Personi i kontaktit"><input value={item.contactName ?? ""} onChange={(event) => patch(item.id, { contactName: event.target.value })} /></Field>
    <Field label="Telefon"><input type="tel" value={item.phone ?? ""} onChange={(event) => patch(item.id, { phone: event.target.value })} /></Field>
    <Field label="Email"><input type="email" value={item.email ?? ""} onChange={(event) => patch(item.id, { email: event.target.value })} /></Field>
    <Field label="Rajonet"><input value={join(item.regions)} onChange={(event) => patch(item.id, { regions: split(event.target.value) })} placeholder="Tiranë, Durrës" /></Field>
    <Field label="Koha e përgjigjes"><input value={item.availability} onChange={(event) => patch(item.id, { availability: event.target.value })} placeholder="p.sh. njoftim 10 ditë" /></Field>
    <Field label="Ditë minimale mobilizimi"><input type="number" min="0" value={item.leadTimeDays ?? ""} onChange={(event) => patch(item.id, { leadTimeDays: numberValue(event.target.value) })} /></Field>
    <Field label="Fushat kryesore" wide><input value={join(item.categories)} onChange={(event) => patch(item.id, { categories: split(event.target.value) })} placeholder="instalime elektrike, fasadë, gjeoteknikë" /></Field>
    <Field label="Licencat dhe certifikimet" wide><input value={join(item.licences)} onChange={(event) => patch(item.id, { licences: split(event.target.value) })} placeholder="NS-14, ISO 9001, laborator i akredituar" /></Field>
    <Field label="CPV-të e mbuluara" wide><input value={join(item.cpvCodes ?? [])} onChange={(event) => patch(item.id, { cpvCodes: split(event.target.value) })} placeholder="45310000, 45443000" /></Field>
    <Field label="Vlera maksimale e angazhimit (ALL)"><input type="number" min="0" value={item.maxContractValueAll ?? ""} onChange={(event) => patch(item.id, { maxContractValueAll: numberValue(event.target.value) })} /></Field>
    <Field label="Projekte maksimale njëkohësisht"><input type="number" min="1" value={item.maxConcurrentProjects ?? ""} onChange={(event) => patch(item.id, { maxConcurrentProjects: numberValue(event.target.value) })} /></Field>
    <Field label="Punë të përjashtuara" wide><input value={join(item.excludedWork ?? [])} onChange={(event) => patch(item.id, { excludedWork: split(event.target.value) })} /></Field>
    <Field label="Rreziku i varësisë"><select value={item.dependencyRisk} onChange={(event) => patch(item.id, { dependencyRisk: event.target.value as CapabilityPartner["dependencyRisk"] })}><option value="low">I ulët</option><option value="medium">Mesatar</option><option value="high">I lartë</option></select></Field>
    <label className="check-field"><input type="checkbox" checked={item.jointVentureReady} onChange={(event) => patch(item.id, { jointVentureReady: event.target.checked })} /><span><b>I gatshëm për bashkim operatorësh</b></span></label>
    <Field label="Shënime dhe kushte" wide><textarea rows={3} value={item.notes ?? ""} onChange={(event) => patch(item.id, { notes: event.target.value })} placeholder="Kufizime, cilësi e pritshme, kushte pagese, dokumente që duhen kërkuar…" /></Field>
    <div className="partner-detail-block field-wide"><div className="partner-detail-heading"><div><b>Aftësitë dhe detyrat</b><small>Çfarë mund të realizojë konkretisht ky partner.</small></div><button type="button" className="add-record" onClick={() => patch(item.id, { capabilities: [...(item.capabilities ?? []), { id: uid("partner-cap"), name: "", category: "", cpvCodes: [], tasks: [], deliveryMode: "execution", headcount: 0, crewCount: 0, availableFrom: null, capacityNotes: "", active: true }] })}>＋ Shto aftësi</button></div>{(item.capabilities ?? []).map((capability) => <div className="partner-mini-grid" key={capability.id}><input aria-label="Emri i aftësisë" value={capability.name} onChange={(event) => patch(item.id, { capabilities: (item.capabilities ?? []).map((current) => current.id === capability.id ? { ...current, name: event.target.value } : current) })} placeholder="p.sh. Instalime elektrike" /><input aria-label="Detyrat e aftësisë" value={join(capability.tasks)} onChange={(event) => patch(item.id, { capabilities: (item.capabilities ?? []).map((current) => current.id === capability.id ? { ...current, tasks: split(event.target.value) } : current) })} placeholder="kabllime, ndriçim, panele" /><input aria-label="CPV e aftësisë" value={join(capability.cpvCodes)} onChange={(event) => patch(item.id, { capabilities: (item.capabilities ?? []).map((current) => current.id === capability.id ? { ...current, cpvCodes: split(event.target.value) } : current) })} placeholder="45310000" /><input type="number" min="0" aria-label="Numri i njerëzve" value={capability.headcount} onChange={(event) => patch(item.id, { capabilities: (item.capabilities ?? []).map((current) => current.id === capability.id ? { ...current, headcount: Number(event.target.value) } : current) })} placeholder="Njerëz" /><button type="button" aria-label="Hiq aftësinë" onClick={() => patch(item.id, { capabilities: (item.capabilities ?? []).filter((current) => current.id !== capability.id) })}>×</button></div>)}</div>
    <div className="partner-detail-block field-wide"><div className="partner-detail-heading"><div><b>Pajisjet dhe makineritë</b><small>Përfshin edhe makineritë që merren me qira nga palë të treta.</small></div><button type="button" className="add-record" onClick={() => patch(item.id, { resources: [...(item.resources ?? []), { id: uid("partner-resource"), resourceType: item.partnerType === "equipment_rental" ? "equipment" : "equipment", name: "", model: "", category: "", quantity: 1, availableQuantity: 1, capacity: "", location: "", availableFrom: null, operatorIncluded: false, fuelIncluded: false, transportIncluded: false, rentalMinimumDays: 1, condition: "good", inspectionExpiry: null, active: true }] })}>＋ Shto pajisje</button></div>{(item.resources ?? []).map((resource) => <div className="partner-mini-grid" key={resource.id}><input aria-label="Emri i pajisjes" value={resource.name} onChange={(event) => patch(item.id, { resources: (item.resources ?? []).map((current) => current.id === resource.id ? { ...current, name: event.target.value } : current) })} placeholder="Ekskavator" /><input aria-label="Modeli i pajisjes" value={resource.model} onChange={(event) => patch(item.id, { resources: (item.resources ?? []).map((current) => current.id === resource.id ? { ...current, model: event.target.value } : current) })} placeholder="CAT 320" /><input aria-label="Kapaciteti i pajisjes" value={resource.capacity} onChange={(event) => patch(item.id, { resources: (item.resources ?? []).map((current) => current.id === resource.id ? { ...current, capacity: event.target.value } : current) })} placeholder="20 ton" /><input type="number" min="0" aria-label="Sasia e disponueshme" value={resource.availableQuantity} onChange={(event) => patch(item.id, { resources: (item.resources ?? []).map((current) => current.id === resource.id ? { ...current, availableQuantity: Number(event.target.value) } : current) })} placeholder="Sasia" /><label className="mini-check"><input type="checkbox" checked={resource.operatorIncluded} onChange={(event) => patch(item.id, { resources: (item.resources ?? []).map((current) => current.id === resource.id ? { ...current, operatorIncluded: event.target.checked } : current) })} /> Operator</label><button type="button" aria-label="Hiq pajisjen" onClick={() => patch(item.id, { resources: (item.resources ?? []).filter((current) => current.id !== resource.id) })}>×</button></div>)}</div>
    <div className="partner-detail-block field-wide"><div className="partner-detail-heading"><div><b>Tarifat dhe kushtet e çmimit</b><small>Ruani tarifa orientuese; oferta konkrete mund të zëvendësojë këto vlera.</small></div><button type="button" className="add-record" onClick={() => patch(item.id, { rates: [...(item.rates ?? []), { id: uid("partner-rate"), scope: "", unit: "day", amountAll: 0, vatIncluded: false, minimumCommitment: null, validFrom: new Date().toISOString().slice(0, 10), validUntil: null, notes: "" }] })}>＋ Shto tarifë</button></div>{(item.rates ?? []).map((rate) => <div className="partner-mini-grid" key={rate.id}><input aria-label="Fusha e tarifës" value={rate.scope} onChange={(event) => patch(item.id, { rates: (item.rates ?? []).map((current) => current.id === rate.id ? { ...current, scope: event.target.value } : current) })} placeholder="Punë elektrike / CAT 320" /><select aria-label="Njësia e tarifës" value={rate.unit} onChange={(event) => patch(item.id, { rates: (item.rates ?? []).map((current) => current.id === rate.id ? { ...current, unit: event.target.value as PartnerRate["unit"] } : current) })}><option value="hour">orë</option><option value="day">ditë</option><option value="month">muaj</option><option value="unit">njësi</option><option value="lump_sum">shumë fikse</option></select><input type="number" min="0" aria-label="Shuma në ALL" value={rate.amountAll} onChange={(event) => patch(item.id, { rates: (item.rates ?? []).map((current) => current.id === rate.id ? { ...current, amountAll: Number(event.target.value) } : current) })} placeholder="ALL" /><input type="date" aria-label="Tarifa vlen deri" value={rate.validUntil ?? ""} onChange={(event) => patch(item.id, { rates: (item.rates ?? []).map((current) => current.id === rate.id ? { ...current, validUntil: event.target.value || null } : current) })} /><label className="mini-check"><input type="checkbox" checked={rate.vatIncluded} onChange={(event) => patch(item.id, { rates: (item.rates ?? []).map((current) => current.id === rate.id ? { ...current, vatIncluded: event.target.checked } : current) })} /> TVSH</label><button type="button" aria-label="Hiq tarifën" onClick={() => patch(item.id, { rates: (item.rates ?? []).filter((current) => current.id !== rate.id) })}>×</button></div>)}</div>
    <div className="partner-detail-block field-wide"><div className="partner-detail-heading"><div><b>Performanca</b><small>Përdoret për transparencë dhe zgjedhje midis partnerëve të barabartë.</small></div></div><div className="partner-performance-grid"><Field label="Projekte të përfunduara"><input type="number" min="0" value={item.performance?.completedProjects ?? 0} onChange={(event) => patch(item.id, { performance: { ...(item.performance ?? { completedProjects: 0, onTimeRate: null, qualityRating: null, lastUsedAt: null, notes: "" }), completedProjects: Number(event.target.value) } })} /></Field><Field label="Përfundim në afat (%)"><input type="number" min="0" max="100" value={item.performance?.onTimeRate ?? ""} onChange={(event) => patch(item.id, { performance: { ...(item.performance ?? { completedProjects: 0, onTimeRate: null, qualityRating: null, lastUsedAt: null, notes: "" }), onTimeRate: numberValue(event.target.value) } })} /></Field><Field label="Vlerësim cilësie (1–5)"><input type="number" min="1" max="5" step="0.1" value={item.performance?.qualityRating ?? ""} onChange={(event) => patch(item.id, { performance: { ...(item.performance ?? { completedProjects: 0, onTimeRate: null, qualityRating: null, lastUsedAt: null, notes: "" }), qualityRating: numberValue(event.target.value) } })} /></Field></div></div>
  </Card>)}</>;
}

function RulesSection({ model, setModel, addCommitment, patchCommitment, removeCommitment }: { model: CompanyCapabilityModel; setModel: SetModel; addCommitment: (item: ActiveCommitment) => void; patchCommitment: Patch<ActiveCommitment>; removeCommitment: (id: string) => void }) {
  const preferences = model.bidPreferences; const patch = (value: Partial<typeof preferences>) => setModel((current) => ({ ...current, bidPreferences: { ...current.bidPreferences, ...value } }));
  const addCommit = () => addCommitment({ id: uid("commitment"), projectName: "", workType: "", startDate: null, endDate: null, committedPeople: 0, committedCrews: 0, committedEquipment: [], active: true });
  const addRule = () => patch({ rules: [...preferences.rules, { id: uid("rule"), name: "", condition: "", severity: "warning", active: true }] });
  const patchRule = (ruleId: string, value: Partial<BidRule>) => patch({ rules: preferences.rules.map((rule) => rule.id === ruleId ? { ...rule, ...value } : rule) });
  return <><SectionIntro title="Preferencat tregtare" copy="Këto rregulla ndikojnë në rekomandim, pa ndryshuar faktet e tenderit." /><div className="record-grid standalone-grid"><Field label="Autoritete të preferuara"><input value={join(preferences.preferredAuthorities)} onChange={(event) => patch({ preferredAuthorities: split(event.target.value) })} /></Field><Field label="Autoritete të përjashtuara"><input value={join(preferences.excludedAuthorities)} onChange={(event) => patch({ excludedAuthorities: split(event.target.value) })} /></Field><Field label="Projekte të preferuara"><input value={join(preferences.preferredProjectTypes)} onChange={(event) => patch({ preferredProjectTypes: split(event.target.value) })} /></Field><Field label="Projekte të përjashtuara"><input value={join(preferences.excludedProjectTypes)} onChange={(event) => patch({ excludedProjectTypes: split(event.target.value) })} /></Field><Field label="Ditë minimale për ofertën"><input type="number" min="0" value={preferences.minimumLeadDays ?? ""} onChange={(event) => patch({ minimumLeadDays: numberValue(event.target.value) })} /></Field><Field label="Kohëzgjatje maksimale (muaj)"><input type="number" min="1" value={preferences.maxContractMonths ?? ""} onChange={(event) => patch({ maxContractMonths: numberValue(event.target.value) })} /></Field><Field label="Projekte maksimale njëkohësisht"><input type="number" min="1" value={preferences.maxConcurrentProjects ?? ""} onChange={(event) => patch({ maxConcurrentProjects: numberValue(event.target.value) })} /></Field><Field label="Afati maksimal i pagesës (ditë)"><input type="number" min="0" value={preferences.acceptedPaymentDays ?? ""} onChange={(event) => patch({ acceptedPaymentDays: numberValue(event.target.value) })} /></Field><Field label="Penalitet maksimal (%)"><input type="number" min="0" max="100" step="0.1" value={preferences.maxLiquidatedDamagesPercent ?? ""} onChange={(event) => patch({ maxLiquidatedDamagesPercent: numberValue(event.target.value) })} /></Field><label className="check-field"><input type="checkbox" checked={preferences.requiresAdvancePayment} onChange={(event) => patch({ requiresAdvancePayment: event.target.checked })} /><span><b>Kërkohet parapagim</b></span></label><label className="check-field"><input type="checkbox" checked={preferences.jointVentureAllowed} onChange={(event) => patch({ jointVentureAllowed: event.target.checked })} /><span><b>Lejo bashkim operatorësh</b></span></label></div><SectionIntro title="Rregulla të personalizuara" copy="Klasifikoni çdo rregull si bllokues, paralajmërim ose preferencë." action="Shto rregull" onAdd={addRule} /><div className="rules-list">{preferences.rules.map((rule) => <div key={rule.id}><input aria-label="Emri i rregullit" value={rule.name} onChange={(event) => patchRule(rule.id, { name: event.target.value })} placeholder="Emri i rregullit" /><input aria-label="Kushti" value={rule.condition} onChange={(event) => patchRule(rule.id, { condition: event.target.value })} placeholder="Përshkruani kushtin" /><select aria-label="Rëndësia" value={rule.severity} onChange={(event) => patchRule(rule.id, { severity: event.target.value as BidRule["severity"] })}><option value="blocker">Bllokues</option><option value="warning">Paralajmërim</option><option value="preference">Preferencë</option></select><button type="button" onClick={() => patch({ rules: preferences.rules.filter((item) => item.id !== rule.id) })}>×</button></div>)}</div><SectionIntro title="Angazhimet aktive" copy="Mbani projektet aktuale që sistemi të mos premtojë burime të zëna." action="Shto angazhim" onAdd={addCommit} />{model.commitments.map((item) => <Card key={item.id} title={item.projectName || "Projekt aktiv"} eyebrow="ANGAZHIM AKTUAL" onRemove={() => removeCommitment(item.id)}><Field label="Projekti" required><input value={item.projectName} onChange={(event) => patchCommitment(item.id, { projectName: event.target.value })} /></Field><Field label="Lloji i punës"><input value={item.workType} onChange={(event) => patchCommitment(item.id, { workType: event.target.value })} /></Field><Field label="Fillimi"><input type="date" value={item.startDate ?? ""} onChange={(event) => patchCommitment(item.id, { startDate: event.target.value || null })} /></Field><Field label="Përfundimi"><input type="date" value={item.endDate ?? ""} onChange={(event) => patchCommitment(item.id, { endDate: event.target.value || null })} /></Field><Field label="Njerëz të angazhuar"><input type="number" min="0" value={item.committedPeople} onChange={(event) => patchCommitment(item.id, { committedPeople: Number(event.target.value) })} /></Field><Field label="Ekipe të angazhuara"><input type="number" min="0" value={item.committedCrews} onChange={(event) => patchCommitment(item.id, { committedCrews: Number(event.target.value) })} /></Field><Field label="Pajisje të angazhuara" wide><input value={join(item.committedEquipment)} onChange={(event) => patchCommitment(item.id, { committedEquipment: split(event.target.value) })} /></Field></Card>)}</>;
}

function DocumentManager({ section, documents, onChange }: { section: CapabilitySectionKey; documents: CapabilityDocument[]; onChange: (documents: CapabilityDocument[]) => void }) {
  const input = useRef<HTMLInputElement>(null); const [uploading, setUploading] = useState(false); const [category, setCategory] = useState("Dokument mbështetës"); const [expiresAt, setExpiresAt] = useState(""); const [error, setError] = useState("");
  async function upload(file: File) {
    setUploading(true); setError("");
    try {
      const form = new FormData(); form.append("file", file); form.append("section", section); form.append("category", category); if (expiresAt) form.append("expiresAt", expiresAt);
      const response = await fetch("/api/company/capability-documents", { method: "POST", body: form });
      const body = await response.json().catch(() => null) as { document?: CapabilityDocument; error?: string } | null;
      if (!response.ok || !body?.document) throw new Error(body?.error ?? "Ngarkimi dështoi.");
      onChange([...documents, body.document]);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Ngarkimi dështoi."); }
    finally { setUploading(false); }
  }
  async function remove(id: string) {
    setError("");
    try {
      const response = await fetch(`/api/company/capability-documents/${encodeURIComponent(id)}`, { method: "DELETE" });
      const body = await response.json().catch(() => null) as { error?: string } | null;
      if (!response.ok) throw new Error(body?.error ?? "Dokumenti nuk u hoq.");
      onChange(documents.filter((item) => item.id !== id));
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Dokumenti nuk u hoq."); }
  }
  return <section className="document-panel"><div><span className="document-icon">↥</span><div><h3>Dokumente mbështetëse</h3><p>PDF, PNG, JPG ose DOCX · maksimumi 15 MB · hapësirë private</p></div></div><div className="document-controls"><input aria-label="Kategoria e dokumentit" value={category} onChange={(event) => setCategory(event.target.value)} /><input aria-label="Data e skadimit" type="date" value={expiresAt} onChange={(event) => setExpiresAt(event.target.value)} /><button type="button" className="secondary-button" disabled={uploading} onClick={() => input.current?.click()}>{uploading ? "Duke ngarkuar…" : "Zgjidh dokument"}</button><input ref={input} hidden type="file" accept=".pdf,.png,.jpg,.jpeg,.docx" onChange={(event) => { const file = event.target.files?.[0]; if (file) void upload(file); event.target.value = ""; }} /></div>{error && <p className="document-error">{error}</p>}{documents.length > 0 && <div className="document-list">{documents.map((document) => <div key={document.id}><span className="pdf-icon">DOC</span><a href={`/api/company/capability-documents/${document.id}`} target="_blank" rel="noreferrer"><b>{document.name}</b><small>{document.category} · {(document.fileSize / 1024).toFixed(0)} KB{document.expiresAt ? ` · skadon ${document.expiresAt}` : ""}</small></a><button type="button" onClick={() => void remove(document.id)} aria-label={`Hiq ${document.name}`}>×</button></div>)}</div>}</section>;
}
